import{c as t,S as a,j as d,m as r}from"./chunks/framework.DBSVVeOL.js";const p=JSON.parse('{"title":"Feature Coverage","description":"","frontmatter":{},"headers":[],"relativePath":"feature-coverage.md","filePath":"feature-coverage.md","lastUpdated":null}'),l={name:"feature-coverage.md"};function s(n,e,i,o,c,u){return a(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="Feature-Coverage" tabindex="-1">Feature Coverage <a class="header-anchor" href="#Feature-Coverage" aria-label="Permalink to &quot;Feature Coverage {#Feature-Coverage}&quot;">​</a></h1><p>This page summarizes the supported surface. The repository root <code>FEATURES_COVERAGE.md</code> remains the detailed tracking file for implementation notes and intentionally omitted edge cases.</p><h2 id="Core-NATS" tabindex="-1">Core NATS <a class="header-anchor" href="#Core-NATS" aria-label="Permalink to &quot;Core NATS {#Core-NATS}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Connect handshake</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Includes typed token, user/password, NKEY, JWT, <code>.creds</code>, and callback authentication, client name, no echo, TLS requirements, and server INFO parsing.</td></tr><tr><td style="text-align:left;">Publish and subscribe</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Includes wildcards, queue groups, INFO-negotiated headers, max payload checks, size- and latency-bound buffered outbound writes, and per-subscription pending limits.</td></tr><tr><td style="text-align:left;">Request reply</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Uses a shared request inbox mux and maps negotiated no-responder status to <code>NoRespondersError</code>.</td></tr><tr><td style="text-align:left;">Direct APIs and task handles</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Direct calls are task-friendly; <code>_async</code> helpers return <code>NatterTask</code> for explicit handle-oriented code, and <code>fetch(handle)</code> returns the sync result or throws the same operation error that the synchronous API would throw.</td></tr><tr><td style="text-align:left;">Flush and ping</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Drains buffered outbound writes and uses PING/PONG synchronization.</td></tr><tr><td style="text-align:left;">Drain and close</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Drains subscriptions and reports cleanup failures.</td></tr><tr><td style="text-align:left;">Automatic reconnect</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Reconnects in the background, emits typed connection events, allows reconnect-delay callback overrides, replays subscriptions, and flushes bounded pending publishes on a best-effort basis. Retained publishes can be delivered more than once after ambiguous transport failures; large direct-write frames are not retained after a successful socket write. Use JetStream <code>msg_id</code> deduplication or idempotent handlers for duplicate-sensitive effects. Real-server coverage includes same-server reconnect and multi-URL failover; multi-node cluster chaos and auth failover need more coverage before treating this as fully hardened cluster behavior.</td></tr><tr><td style="text-align:left;">Discovered servers</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Server-discovered URLs are retained for reconnects, and stale discovered routes are pruned on subsequent INFO updates.</td></tr><tr><td style="text-align:left;">Server errors</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Permission violations are reported without reconnecting; repeated auth failures abort reconnect with auth-specific errors.</td></tr><tr><td style="text-align:left;">Slow consumer handling</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Drops over-limit messages and reports <code>SlowConsumerError</code>.</td></tr><tr><td style="text-align:left;">WebSocket transport</td><td style="text-align:left;">Not implemented</td><td style="text-align:left;">Planned only if there is clear demand.</td></tr></tbody></table><h2 id="TLS-And-Security" tabindex="-1">TLS And Security <a class="header-anchor" href="#TLS-And-Security" aria-label="Permalink to &quot;TLS And Security {#TLS-And-Security}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">TLS-first handshake</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>tls://</code> defaults to TLS before INFO.</td></tr><tr><td style="text-align:left;">INFO-first TLS upgrade</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Use <code>tls_first=false</code> for deployments that require it.</td></tr><tr><td style="text-align:left;">CA and client certificates</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>tls_ca_path</code>, <code>tls_cert_path</code>, and <code>tls_key_path</code>.</td></tr><tr><td style="text-align:left;">Server-name and IP SAN verification</td><td style="text-align:left;">Supported</td><td style="text-align:left;">The URL host is verified by default; IP-literal hosts match <code>iPAddress</code> subject alternative names, and <code>tls_server_name</code> overrides SNI and certificate-name validation.</td></tr><tr><td style="text-align:left;">Disable certificate verification</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>tls_verify=false</code>; intended only for trusted environments.</td></tr><tr><td style="text-align:left;">Token auth</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>TokenAuth</code> or URL userinfo when <code>auth=NoAuth()</code>. Option tokens are stored in redacted wipeable buffers, and token values are redacted from <code>ConnectOptions</code> display including URL userinfo.</td></tr><tr><td style="text-align:left;">Username/password auth</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>UserPassAuth</code> or URL userinfo when <code>auth=NoAuth()</code>. Option passwords are stored in redacted wipeable buffers, and users/passwords are redacted from <code>ConnectOptions</code> display including URL userinfo.</td></tr><tr><td style="text-align:left;">NKEY auth</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>NKeyAuth</code> supports public user NKEY plus signing callback and user seed-backed NKEY auth. NKEY seeds are stored in redacted wipeable buffers, path-loaded seed input buffers are wiped after CONNECT fields are derived, non-user NKEY prefixes are rejected locally, and unit plus CI real-server coverage are available.</td></tr><tr><td style="text-align:left;">JWT and <code>.creds</code> auth</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>JwtAuth</code> and <code>CredentialsAuth</code> support user JWT plus seed/callback and <code>.creds</code> content or file parsing. JWT and inline credentials are stored in redacted wipeable buffers, path-loaded auth input buffers are wiped after CONNECT fields are derived, CONNECT serialization and parsing are unit-tested, and CI real-server coverage runs with generated NSC credentials.</td></tr><tr><td style="text-align:left;">Dynamic auth callback</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>CallbackAuth</code> receives <code>AuthRequest</code> after server <code>INFO</code> on initial connect and reconnect and returns a concrete static auth value.</td></tr></tbody></table><h2 id="JetStream" tabindex="-1">JetStream <a class="header-anchor" href="#JetStream" aria-label="Permalink to &quot;JetStream {#JetStream}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Typed stream configs</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Mirrors known stream schema fields with Julia structs and EnumX enums, plus local subject/name/numeric validation.</td></tr><tr><td style="text-align:left;">Typed consumer configs</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Mirrors known consumer schema fields with Julia structs and EnumX enums, plus local subject/name/queue/numeric validation.</td></tr><tr><td style="text-align:left;">Raw config dictionaries</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Escape hatch for newer server fields.</td></tr><tr><td style="text-align:left;">Stream CRUD and list APIs</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Includes pagination and typed stream info state.</td></tr><tr><td style="text-align:left;">Consumer CRUD and list APIs</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Includes typed consumer info counters/cursors, server-version-aware create subjects, strict create/update actions, and explicit create-or-update upsert.</td></tr><tr><td style="text-align:left;">Publish acknowledgements</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>js_publish</code> returns <code>PubAck</code> and exposes first-class headers for msg-id, expected stream/sequence/msg-id/subject, per-message TTL, schedules, and no-responders retry.</td></tr><tr><td style="text-align:left;">Task handle helpers</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Management, publish, message get/delete, consumer, fetch, close, and ack operations have <code>_async</code> helpers.</td></tr><tr><td style="text-align:left;">Pull consumers</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Durable and named consumers bind without mutation and recover from concurrent matching strict-create conflicts; missing consumers and random ephemerals are strictly created. Batch fetch, <code>max_bytes</code>, <code>no_wait</code>, threshold-refilled <code>messages</code>, callback <code>consume</code>, priority scheduling request fields, per-request reply correlation, expiration handling, idle heartbeat monitoring, reconnect-disconnect reporting, and JetStream status/control error mapping are covered. Continuous stream refill is based on buffered/requested client messages and bytes and caps pulls by <code>channel_size</code>, <code>max_bytes</code>, and <code>stop_after</code>. Only one active fetch or stream may use a pull subscription at a time, and pull requests are not replayed after reconnect; callers retry bounded fetches after <code>FetchDisconnectedError</code>, while streams surface errors through <code>wait(stream)</code>/<code>fetch(stream)</code>.</td></tr><tr><td style="text-align:left;">Push consumers</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Durable and named consumers bind without mutation and recover from concurrent matching strict-create conflicts by rebinding to the existing deliver subject; active non-queue push consumers reject a second bind, and existing queue consumers require an explicit matching queue. Queue groups, callbacks, and manual or automatic acknowledgement are supported. Non-queue push consumers also support idle heartbeat filtering, missed-heartbeat reporting, flow-control replies, and lifecycle status reporting.</td></tr><tr><td style="text-align:left;">Message acknowledgements</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>ack</code>, <code>ack_sync</code>, <code>nak</code>, <code>in_progress</code>, and <code>term</code>.</td></tr><tr><td style="text-align:left;">Message get</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Sequence, last by subject, next by subject, and direct get.</td></tr><tr><td style="text-align:left;">Ordered consumers</td><td style="text-align:left;">Not implemented</td><td style="text-align:left;">Can be added later if needed.</td></tr><tr><td style="text-align:left;">Object store</td><td style="text-align:left;">Not implemented</td><td style="text-align:left;">Outside the current high-value surface.</td></tr></tbody></table><h2 id="KeyValue" tabindex="-1">KeyValue <a class="header-anchor" href="#KeyValue" aria-label="Permalink to &quot;KeyValue {#KeyValue}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Bucket create/open/delete/status</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Backed by JetStream streams; <code>kv_create</code> exposes history, bucket TTL, max bucket bytes, max value size, storage, replicas, direct reads, compression, metadata, and delete-marker TTL. History is locally limited to 1 through 64. Bucket operations accept per-call timeouts.</td></tr><tr><td style="text-align:left;">Put/create/update</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Return the new KV revision and include optimistic revision checks, create after delete/purge markers, per-key TTL headers, KV-specific conflict errors, and per-call timeouts.</td></tr><tr><td style="text-align:left;">Get by latest or revision</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Returns typed entries with key, value, revision, created timestamp, delta, and operation. Direct reads are used when bucket direct access is enabled; missing and deleted keys raise KV-specific errors. Gets accept per-call timeouts.</td></tr><tr><td style="text-align:left;">Delete and purge</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Uses KeyValue operation headers, optional expected-revision checks, purge marker TTL, delete-marker cleanup, and per-call timeouts.</td></tr><tr><td style="text-align:left;">History and keys</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Implemented through pull consumers; history returns typed entries. History and key listing use one per-call timeout budget across consumer setup and fetch pagination.</td></tr><tr><td style="text-align:left;">Watch</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Implemented through ordinary push consumers with callback or <code>KeyValueWatcher</code> channel APIs. Supports multiple filters, updates-only, history, ignore-deletes, metadata-only delivery, resume revision, per-call setup timeout, and an initial-done sentinel. Ordered-consumer gap/reset behavior is not implemented yet.</td></tr><tr><td style="text-align:left;">Task handle helpers</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Bucket, status, key, history, keys, watch, and watcher close operations have <code>_async</code> helpers.</td></tr></tbody></table>',10)])])}const y=t(l,[["render",s]]);export{p as __pageData,y as default};
